unitsize(0.2inch);
defaultpen(linewidth(0.7));
real f(real y)
{
  return (5*sqrt(3)-y)/sqrt(3);
}
draw((-5,0)--(5,0)--(0,5*sqrt(3))--cycle);
draw((-f(5*sqrt(3)/4),5*sqrt(3)/4)--(f(5*sqrt(3)/4),5*sqrt(3)/4));
draw((-f(5*sqrt(3)/2),5*sqrt(3)/2)--(f(5*sqrt(3)/2),5*sqrt(3)/2));
